package com.flowdesk.ticket;
import com.flowdesk.security.*; import com.flowdesk.core.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import jakarta.persistence.criteria.Predicate; import java.time.*; import java.util.*;
@Service public class TicketService {
 private final TicketRepository tickets; private final UserRepository users; private final TicketAuditRepository audits; private final NotificationRepository notifications; private final Clock clock;private final JdbcTemplate jdbc;
 public TicketService(TicketRepository t,UserRepository u,TicketAuditRepository a,NotificationRepository n,Clock clock,JdbcTemplate jdbc){tickets=t;users=u;audits=a;notifications=n;this.clock=clock;this.jdbc=jdbc;}
 @Transactional public Ticket create(CreateTicket r,String actor){var active=jdbc.queryForObject("select count(*) from categories where name=? and active=true",Long.class,r.category());if(active==null||active==0)throw new ConflictException("Kategori bulunamadı veya pasif.");var creator=user(actor);var t=tickets.save(new Ticket("FD-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(),r.title(),r.description(),r.category(),r.priority(),creator,clock.instant()));audit(t,"CREATED",actor,"",t.getStatus(),null);return t;}
 @Transactional(readOnly=true) public Page<Ticket> list(String actor,boolean all,String status,String priority,String category,String assignee,String q,Instant from,Instant to,Boolean breached,int page,int size){Pageable pageable=PageRequest.of(page,Math.min(size,100),all?Sort.by(Sort.Order.asc("priority")).and(Sort.by("slaDueAt")).and(Sort.by("createdAt")).and(Sort.by("id")):Sort.by("createdAt").descending());if(!all)return tickets.findByCreatedByUsernameOrAssigneeUsername(actor,actor,pageable);Specification<Ticket> spec=(root,query,cb)->{List<Predicate> p=new ArrayList<>();if(status!=null&&!status.isBlank())p.add(cb.equal(root.get("status"),status));if(priority!=null&&!priority.isBlank())p.add(cb.equal(root.get("priority"),priority));if(category!=null&&!category.isBlank())p.add(cb.equal(root.get("category"),category));if(assignee!=null&&!assignee.isBlank())p.add(cb.equal(root.get("assignee").get("username"),assignee));if(q!=null&&!q.isBlank()){String like="%"+q.toLowerCase()+"%";p.add(cb.or(cb.like(cb.lower(root.get("title")),like),cb.like(cb.lower(root.get("description")),like),cb.like(cb.lower(root.get("ticketNumber")),like)));}if(from!=null)p.add(cb.greaterThanOrEqualTo(root.get("createdAt"),from));if(to!=null)p.add(cb.lessThanOrEqualTo(root.get("createdAt"),to));if(breached!=null){Predicate terminal=root.get("status").in("COMPLETED","CANCELLED");Predicate overdue=cb.lessThan(root.get("slaDueAt"),clock.instant());p.add(breached?cb.and(cb.not(terminal),overdue):cb.or(terminal,cb.not(overdue)));}return cb.and(p.toArray(Predicate[]::new));};return tickets.findAll(spec,pageable);}
 @Transactional(readOnly=true) public Ticket get(long id,String actor,boolean all){var t=one(id);if(!all&&!t.getCreatedBy().getUsername().equals(actor)&&(t.getAssignee()==null||!t.getAssignee().getUsername().equals(actor)))throw new ForbiddenException();return t;}
 @Transactional public Ticket assign(long id,String assignee,String actor){var t=one(id);if(List.of("COMPLETED","CANCELLED").contains(t.getStatus()))throw new ConflictException("Terminal durumdaki talep atanamaz.");String prev=t.getStatus();var u=user(assignee);if(!u.getRoles().contains("EMPLOYEE"))throw new ConflictException("Talep yalnızca çalışan rolündeki kullanıcıya atanabilir.");t.assign(u,clock.instant());audit(t,"ASSIGNED",actor,prev,"ASSIGNED",assignee);notifications.save(new Notification(assignee,"ASSIGNED","Yeni iş size atandı: "+t.getTitle(),t.getTicketNumber(),clock.instant()));return tickets.saveAndFlush(t);}
 @Transactional public Ticket setPriority(long id,String priority,String reason,String actor){if(reason==null||reason.isBlank())throw new ConflictException("Öncelik değişikliği için gerekçe zorunludur.");var t=one(id);if(List.of("COMPLETED","CANCELLED").contains(t.getStatus()))throw new ConflictException("Terminal durumdaki talebin önceliği değiştirilemez.");String old=t.getPriority();t.priority(priority,clock.instant());audit(t,"PRIORITY_CHANGED",actor,old,priority,reason);if(t.getAssignee()!=null)notifications.save(new Notification(t.getAssignee().getUsername(),"PRIORITY_CHANGED","Öncelik güncellendi: "+t.getTicketNumber(),t.getTicketNumber(),clock.instant()));return tickets.saveAndFlush(t);}
 @Transactional public Ticket transition(long id,String action,String reason,String actor,Set<String> roles){var t=one(id);String before=t.getStatus();boolean manager=roles.contains("MANAGER")||roles.contains("ADMIN");String next=TicketWorkflow.next(action,before,t.getCreatedBy().getUsername(),t.getAssignee()==null?null:t.getAssignee().getUsername(),actor,manager,reason);
  t.changeStatus(next,clock.instant());audit(t,action,actor,before,next,reason);if((action.equals("APPROVE")||action.equals("REJECT"))&&t.getAssignee()!=null)notifications.save(new Notification(t.getAssignee().getUsername(),action,"Talep "+(action.equals("APPROVE")?"onaylandı":"reddedildi")+": "+t.getTicketNumber(),t.getTicketNumber(),clock.instant()));return tickets.saveAndFlush(t);
 }
 @Transactional public Ticket comment(long id,String text,String actor){var t=get(id,actor,false);audit(t,"COMMENT_ADDED",actor,"",text,null);return t;}
 @Transactional(readOnly=true) public List<TicketAudit> history(String no){return audits.findByTicketNumberOrderByOccurredAtDesc(no);}
 @Transactional(readOnly=true) public List<TicketAudit> allAudit(){return audits.findAll(Sort.by(Sort.Direction.DESC,"occurredAt"));}
 @Transactional public List<Notification> myNotifications(String actor){return notifications.findByUsernameOrderByCreatedAtDesc(actor);}
 @Transactional public Notification markRead(long id,String actor){var n=notifications.findById(id).orElseThrow(()->new NotFoundException());if(!n.getUsername().equals(actor))throw new ForbiddenException();n.markRead();return n;}
 @Transactional public int checkSla(){int count=0;for(var t:tickets.findByStatusNotInAndSlaDueAtBefore(List.of("COMPLETED","CANCELLED"),clock.instant()))if(t.getAssignee()!=null&&!notifications.existsByTypeAndTicketNumber("SLA_BREACH",t.getTicketNumber())){notifications.save(new Notification(t.getAssignee().getUsername(),"SLA_BREACH","SLA aşıldı: "+t.getTicketNumber(),t.getTicketNumber(),clock.instant()));count++;}return count;}
 private void audit(Ticket t,String action,String actor,String old,String next,String reason){audits.save(new TicketAudit(t.getTicketNumber(),action,actor,clock.instant(),old,next,reason));}
 private Ticket one(long id){return tickets.findById(id).orElseThrow(NotFoundException::new);} private UserAccount user(String name){return users.findByUsername(name).orElseThrow(NotFoundException::new);}
 public record CreateTicket(String title,String description,String category,String priority){}
}
